int bnep_add_connection(struct bnep_connadd_req *req, struct socket *sock) {
    struct net_device *dev;
    struct bnep_session *session;
    int err;

    dev = alloc_netdev(0, "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    /* Retrieve source and destination addresses */
    dev->perm_addr[0] = req->src_lap[0];
    dev->perm_addr[1] = req->src_lap[1];
    dev->perm_addr[2] = req->src_lap[2];
    dev->perm_addr[3] = req->src_lap[3];
    dev->perm_addr[4] = req->src_lap[4];
    dev->perm_addr[5] = req->src_lap[5];

    if (is_session_existing(dev->perm_addr)) {
        if (is_session_connected(dev->perm_addr))
            return -EEXIST;
    }

    session = kzalloc(sizeof(*session), GFP_KERNEL);
    if (!session) {
        free_netdev(dev);
        return -ENOMEM;
    }

    session->dev = dev;
    session->sock = sock;
    session->role = req->role;

    /* Setup multicast and protocol filters if configured */
    if (req->multicast_filters) {
        err = setup_multicast_filters(session);
        if (err) {
            kfree(session);
            free_netdev(dev);
            return err;
        }
    }

    if (req->protocol_filters) {
        err = setup_protocol_filters(session);
        if (err) {
            kfree(session);
            free_netdev(dev);
            return err;
        }
    }

    err = register_netdev(dev);
    if (err) {
        kfree(session);
        free_netdev(dev);
        return err;
    }

    err = kernel_thread(bnep_session_handler, session, CLONE_KERNEL);
    if (err < 0) {
        unregister_netdev(dev);
        kfree(session);
        free_netdev(dev);
        return err;
    }

    req->dev_name[0] = '\0';
    strlcpy(req->dev_name, dev->name, IFNAMSIZ);

    return 0;
}

int bnep_connadd(struct bnep_connadd_req *req, struct socket *sock)
{
    struct bnep_session *session;
    struct net_device *dev;
    int err;

    dev = alloc_netdev(sizeof(struct bnep_session), "bnep%d",
                       NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    session = netdev_priv(dev);
    session->dev = dev;
    session->sock = sock;
    memcpy(session->src, req->src, 6);
    memcpy(session->dst, req->dst, 6);
    session->role = req->role;

    if (bnep_session_exists(session->dst)) {
        err = -EEXIST;
        goto error;
    }

    if (req->filter_multicast)
        dev->flags |= IFF_MULTICAST;

    if (req->filter_protocol)
        dev->flags |= IFF_PROMISC;

    err = register_netdev(dev);
    if (err)
        goto error;

    session->thread = kthread_run(bnep_session_handler, session, "bnepd");
    if (IS_ERR(session->thread)) {
        err = PTR_ERR(session->thread);
        goto error_unregister;
    }

    memcpy(req->dev_name, dev->name, IFNAMSIZ);
    return 0;

error_unregister:
    unregister_netdev(dev);
error:
    free_netdev(dev);
    return err;
}

int bnep_connadd(struct bnep_connadd_req *req, struct socket *sock)
{
    struct bnep_session *session;
    struct net_device *dev;
    int err;

    dev = alloc_netdev(sizeof(struct bnep_session), "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    session = netdev_priv(dev);
    session->dev = dev;
    session->sock = sock;
    memcpy(&session->req, req, sizeof(*req));

    if (req->role == BNEP_ROLE_CLIENT)
        session->is_client = 1;

    if (bnep_session_exists(session->dst_laddr)) {
        err = -EEXIST;
        goto free_dev;
    }

    err = register_netdev(dev);
    if (err)
        goto free_dev;

    if (session->req.flags & BNEP_CONNADD_FLAG_MC_FILTER) {
        err = bnep_setup_multicast_filters(session);
        if (err)
            goto unregister_dev;
    }

    if (session->req.flags & BNEP_CONNADD_FLAG_PROTO_FILTER) {
        err = bnep_setup_protocol_filters(session);
        if (err)
            goto unregister_dev;
    }

    err = kernel_thread(bnep_session_handler, session, 0);
    if (err < 0)
        goto unregister_dev;

    memcpy(req->dev_name, dev->name, IFNAMSIZ);

    return 0;

unregister_dev:
    unregister_netdev(dev);
free_dev:
    free_netdev(dev);
    return err;
}

int bnep_connadd(struct bnep_connadd_req *req, struct socket *sock)
{
    struct bnep_session *session;
    struct net_device *dev;
    int err;

    dev = alloc_netdev(sizeof(struct bnep_session), "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    session = netdev_priv(dev);
    session->sock = sock;
    session->role = req->role;

    if (session_exists(req->dst)) {
        err = -EEXIST;
        goto out;
    }

    if (session_is_connected(req->dst)) {
        err = -EBUSY;
        goto out;
    }

    session->src = req->src;
    session->dst = req->dst;
    memcpy(&session->dst_laddr, &req->dst_laddr, sizeof(req->dst_laddr));
    memcpy(&session->src_laddr, &req->src_laddr, sizeof(req->src_laddr));

    if (req->flags & BNEP_CONNADD_FLAGS_MULTICAST)
        session->flags |= BNEP_CONN_FLAGS_MULTICAST;

    if (req->flags & BNEP_CONNADD_FLAGS_PROTO_FILTER) {
        session->proto_filters = kmalloc(sizeof(struct bnep_proto_filters), GFP_KERNEL);
        if (!session->proto_filters) {
            err = -ENOMEM;
            goto out;
        }
        memcpy(session->proto_filters, &req->proto_filters, sizeof(struct bnep_proto_filters));
    }

    dev->netdev_ops = &bnep_netdev_ops;
    dev->needs_free_netdev = 1;

    err = register_netdev(dev);
    if (err)
        goto out;

    session->thread = kthread_run(bnep_session_thread, session, "bnep_session");
    if (IS_ERR(session->thread)) {
        err = PTR_ERR(session->thread);
        goto out_unregister;
    }

    req->dev_name[0] = '\0';
    strncpy(req->dev_name, dev->name, IFNAMSIZ - 1);

    return 0;

out_unregister:
    unregister_netdev(dev);
out:
    free_netdev(dev);
    return err;
}
